import { intrinsicSizeMeasureFunc } from '../tools/utils.ts'
import Yoga from '@hanzo/layout';
import {
  Align,
  BoxSizing,
  Direction,
  Display,
  Edge,
  Errata,
  ExperimentalFeature,
  FlexDirection,
  GridTrackType,
  Gutter,
  Justify,
  MeasureMode,
  Overflow,
  PositionType,
  Unit,
  Wrap,
} from '@hanzo/layout';

test('grid_align_items_baseline_child_margin_percent', () => {
  const config = Yoga.Config.create();

  const root = Yoga.Node.create(config);
  root.setPositionType(PositionType.Absolute);
  root.setDisplay(Display.Grid);
  root.setWidth(100);
  root.setHeight(100);
  root.setAlignItems(Align.Baseline);

  const root_child0 = Yoga.Node.create(config);
  root_child0.setDisplay(Display.Grid);
  root_child0.setWidth(50);
  root_child0.setHeight(50);
  root_child0.setMargin(Edge.All, "5%");
  root.insertChild(root_child0, 0);

  const root_child1 = Yoga.Node.create(config);
  root_child1.setDisplay(Display.Grid);
  root_child1.setWidth(50);
  root_child1.setHeight(20);
  root.insertChild(root_child1, 1);

  const root_child1_child0 = Yoga.Node.create(config);
  root_child1_child0.setDisplay(Display.Grid);
  root_child1_child0.setWidth(50);
  root_child1_child0.setHeight(10);
  root_child1_child0.setMargin(Edge.All, "1%");
  root_child1.insertChild(root_child1_child0, 0);
  root.calculateLayout(undefined, undefined, Direction.LTR);

  expect(root.getComputedLeft()).toBe(0);
  expect(root.getComputedTop()).toBe(0);
  expect(root.getComputedWidth()).toBe(100);
  expect(root.getComputedHeight()).toBe(100);

  expect(root_child0.getComputedLeft()).toBe(3);
  expect(root_child0.getComputedTop()).toBe(3);
  expect(root_child0.getComputedWidth()).toBe(50);
  expect(root_child0.getComputedHeight()).toBe(50);

  expect(root_child1.getComputedLeft()).toBe(0);
  expect(root_child1.getComputedTop()).toBe(55);
  expect(root_child1.getComputedWidth()).toBe(50);
  expect(root_child1.getComputedHeight()).toBe(20);

  expect(root_child1_child0.getComputedLeft()).toBe(1);
  expect(root_child1_child0.getComputedTop()).toBe(1);
  expect(root_child1_child0.getComputedWidth()).toBe(50);
  expect(root_child1_child0.getComputedHeight()).toBe(10);

  root.calculateLayout(undefined, undefined, Direction.RTL);

  expect(root.getComputedLeft()).toBe(0);
  expect(root.getComputedTop()).toBe(0);
  expect(root.getComputedWidth()).toBe(100);
  expect(root.getComputedHeight()).toBe(100);

  expect(root_child0.getComputedLeft()).toBe(48);
  expect(root_child0.getComputedTop()).toBe(3);
  expect(root_child0.getComputedWidth()).toBe(50);
  expect(root_child0.getComputedHeight()).toBe(50);

  expect(root_child1.getComputedLeft()).toBe(50);
  expect(root_child1.getComputedTop()).toBe(55);
  expect(root_child1.getComputedWidth()).toBe(50);
  expect(root_child1.getComputedHeight()).toBe(20);

  expect(root_child1_child0.getComputedLeft()).toBe(0);
  expect(root_child1_child0.getComputedTop()).toBe(1);
  expect(root_child1_child0.getComputedWidth()).toBe(50);
  expect(root_child1_child0.getComputedHeight()).toBe(10);
});
